ValidationRule.errorConditionFormula:
AND($Setup.EnableValidationRule__c.VR_QCC_PrimaryRootCauseNonEditable__c=TRUE,
    OR(
        AND(
            ISCHANGED( Root_Cause__c ),
            NOT(ISBLANK(PRIORVALUE(Root_Cause__c)))
        ),
        AND(
            ISCHANGED(Primary_Root_Cause__c),
            NOT(ISBLANK(PRIORVALUE(Primary_Root_Cause__c)))
        )
    ),
    $Profile.Name <> "Salesforce API Only System Integrations"
)
